'use client';

import { useQuery } from '@tanstack/react-query';
import { useRouter } from 'next/navigation';
import { api } from '@/lib/api';
import { useAuthStore } from '@/store/auth';
import type { DashboardStats } from '@crm/types';
import { Badge } from '@/components/ui/Badge';

const ROLE_LABELS = { admin:'Администратор', supervisor:'Руководитель', manager:'Менеджер', analyst:'Аналитик' } as const;
const PRIORITY_COLOR = { high:'bg-red-500', medium:'bg-amber-500', low:'bg-green-500' } as const;
const STATUS_LABEL   = { active:'Активный', pending:'На рассмотрении', inactive:'Неактивный' } as const;
const STATUS_VARIANT = { active:'green', pending:'orange', inactive:'gray' } as const;

export default function DashboardPage() {
  const user   = useAuthStore(s => s.user);
  const router = useRouter();

  const { data, isLoading } = useQuery<DashboardStats>({
    queryKey: ['dashboard'],
    queryFn:  () => api.get('/dashboard'),
  });

  if (isLoading || !data) {
    return <div className="flex items-center justify-center h-64 text-gray-400 text-sm">Загрузка...</div>;
  }

  return (
    <div>
      <div className="text-sm text-gray-400 mb-1">
        Добро пожаловать, {user?.name.split(' ')[0]} · {ROLE_LABELS[user?.role ?? 'manager']}
      </div>
      <div className="flex items-center justify-between mb-5">
        <h2 className="text-2xl font-extrabold tracking-tight">Обзор</h2>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-4 gap-4 mb-6">
        {[
          { label: 'Клиентов',       value: data.clientCount,   sub: 'в базе CRM' },
          { label: 'Активных сделок', value: data.activeDeals,  sub: 'в воронке' },
          { label: 'Открытых задач', value: data.openTasks,     sub: 'требуют внимания' },
          { label: 'Pipeline',       value: data.pipelineTotal, sub: 'потенциальных', large: true },
        ].map(s => (
          <div key={s.label} className="bg-white border border-gray-200 rounded-xl p-5">
            <div className="text-xs font-semibold uppercase tracking-wider text-gray-400 mb-2">{s.label}</div>
            <div className={`font-extrabold tracking-tight text-gray-900 ${s.large ? 'text-xl' : 'text-3xl'}`}>{s.value}</div>
            <div className="text-xs text-gray-400 mt-1">{s.sub}</div>
          </div>
        ))}
      </div>

      {/* Two columns */}
      <div className="grid grid-cols-2 gap-4">
        {/* Tasks */}
        <div className="bg-white border border-gray-200 rounded-xl overflow-hidden">
          <div className="flex items-center justify-between px-5 py-3.5 border-b border-gray-100">
            <div className="text-sm font-semibold">Ближайшие задачи</div>
            <button onClick={() => router.push('/tasks')} className="text-xs text-gray-400 hover:text-gray-700">Все задачи</button>
          </div>
          {data.todayTasks.length === 0 ? (
            <div className="py-8 text-center text-sm text-gray-400">Нет задач</div>
          ) : (
            data.todayTasks.map(t => (
              <div key={t.id} onClick={() => router.push('/tasks')}
                className={`flex items-center gap-3 px-5 py-3 border-b border-gray-100 last:border-0 cursor-pointer hover:bg-gray-50 ${t.done ? 'opacity-50' : ''}`}>
                <div className={`w-4 h-4 rounded-full border-2 flex-shrink-0 flex items-center justify-center ${t.done ? 'bg-green-500 border-green-500' : 'border-gray-300'}`}>
                  {!!t.done && <svg width="8" height="8" viewBox="0 0 8 8" fill="none"><path d="M1.5 4l2 2L6.5 2" stroke="white" strokeWidth="1.5" strokeLinecap="round"/></svg>}
                </div>
                <div className={`w-2 h-2 rounded-full flex-shrink-0 ${PRIORITY_COLOR[t.priority]}`}/>
                <div className="flex-1 min-w-0">
                  <div className={`text-sm font-medium truncate ${t.done ? 'line-through text-gray-400' : ''}`}>{t.title}</div>
                  {t.client_name && <div className="text-xs text-gray-400">{t.client_name}</div>}
                </div>
                <div className="text-xs text-gray-400 flex-shrink-0">{t.due}</div>
              </div>
            ))
          )}
        </div>

        {/* Clients */}
        <div className="bg-white border border-gray-200 rounded-xl overflow-hidden">
          <div className="flex items-center justify-between px-5 py-3.5 border-b border-gray-100">
            <div className="text-sm font-semibold">Последние клиенты</div>
            <button onClick={() => router.push('/clients')} className="text-xs text-gray-400 hover:text-gray-700">Все клиенты</button>
          </div>
          <table className="w-full">
            <tbody>
              {data.myClients.map(c => (
                <tr key={c.id} onClick={() => router.push(`/clients/${c.id}`)}
                  className="cursor-pointer hover:bg-gray-50 border-b border-gray-100 last:border-0">
                  <td className="px-5 py-3">
                    <div className="text-sm font-semibold">{c.name}</div>
                    <div className="text-xs text-gray-400">{c.industry}</div>
                  </td>
                  <td className="px-3 py-3">
                    <Badge variant={STATUS_VARIANT[c.status]}>{STATUS_LABEL[c.status]}</Badge>
                  </td>
                  <td className="px-5 py-3 text-xs text-gray-400 text-right">{c.last_contact}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
